use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times to offer the notification before giving up.
const NOTIFY_ATTEMPTS: u32 = 3;

/// The key in the shared store that holds the most recent input.
const LAST_INPUT_KEY: &str = "last-input";

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // The graph's author granted `state-rw` ahead of the next graph
        // release. Each call records its input under `last-input`. This does
        // not change the output.
        state_rw::put(LAST_INPUT_KEY, &feed_url);

        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTP: one permitted fetch. A transport failure comes back as a
        // value and counts as zero characters fetched. A host outside the
        // allowlist traps at the boundary, which is intended.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: the contract requires `notified == true`. Retry a few
        // times. If the channel still refuses, trap rather than emit an
        // output that violates the ensures clause.
        let message = format!(
            "heartbeat: t={}s, fetched {} chars from feed",
            seconds, fetched
        );
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notifier refused the heartbeat; refusing to violate `ensures notified == true`");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

